<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';msp2RequireAccess();
$q=msp2NormalizeText((string)($_GET['q']??''));$alerta=strtoupper(trim((string)($_GET['alerta']??'')));$estado=strtoupper(trim((string)($_GET['estado']??'')));$conditions=['1=1'];$params=[];if($q!==''){$conditions[]="(nombre_locatario LIKE :q OR rut LIKE :q OR nombre_comercial LIKE :q OR cdo_local LIKE :q OR CAST(id_contrato_arriendo AS NVARCHAR(20)) LIKE :q)";$params[':q']='%'.$q.'%';}if($alerta!==''){$conditions[]='alerta_codigo=:alerta';$params[':alerta']=$alerta;}if($estado!==''){$conditions[]='estado_recepcion=:estado';$params[':estado']=$estado;}$stmt=$conn->prepare('SELECT * FROM dbo.msp_vw_garantias_control_integral WHERE '.implode(' AND ',$conditions).' ORDER BY alerta_nivel DESC,nombre_locatario,cdo_local');$stmt->execute($params);
$filename='control_garantias_'.date('Ymd_His').'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,['Garantía','Contrato','Arrendatario','RUT','Tienda','Local','Pactado','Recibido','Pendiente recepción','Disponible','Reservado','Aplicado','Devuelto','Estado recepción','Alerta','Descripción'],';');while($r=$stmt->fetch()){fputcsv($out,[$r['id_garantia'],$r['id_contrato_arriendo'],$r['nombre_locatario'],$r['rut'],$r['nombre_comercial'],$r['cdo_local'],$r['monto_pactado'],$r['monto_recibido'],$r['monto_pendiente_recepcion'],$r['monto_disponible'],$r['monto_reservado'],$r['monto_aplicado'],$r['monto_devuelto'],$r['estado_recepcion'],$r['alerta_codigo'],$r['alerta_descripcion']],';');}fclose($out);exit;
